import{_ as a,c as n,a as r,o as d}from"./app-C5hlGzJE.js";const i={};function c(p,e){return d(),n("div",null,e[0]||(e[0]=[r('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-10-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-10-资讯日报"><span>2026-09-10 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="黄仁勋翻车-谷歌tpu凿穿cuda护城河" tabindex="-1"><a class="header-anchor" href="#黄仁勋翻车-谷歌tpu凿穿cuda护城河"><span>黄仁勋翻车，谷歌TPU凿穿CUDA护城河</span></a></h3><p>SemiAnalysis：第三方测试显示，谷歌第七代TPU Ironwood推理每美元性能最高领先英伟达B200达50%，领先B300近一倍，谷歌代码重构打破了CUDA生态壁垒。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0e45c67680643dfec87ade4e15bf24774674f47ce9a9ff1b25c3173ffb4c06f280dd96071b8&amp;idx=2&amp;mid=2652724610&amp;sn=fcfa4e1850bd0fe059c6857ffe6823eb#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ox-alpha揭晓为glm-5-3-flash" tabindex="-1"><a class="header-anchor" href="#ox-alpha揭晓为glm-5-3-flash"><span>Ox Alpha揭晓为GLM-5.3-Flash</span></a></h3><p>Z.ai揭晓，此前在OpenRouter爆火的匿名模型Ox Alpha，正是自家原生多模态大模型GLM-5.3-Flash。该模型开放权重，性能接近顶尖模型，成本远低于同类，可免费下载，由国产芯片支持。<a href="https://mp.weixin.qq.com/s?__biz=MzIxNzI0ODE4Nw==&amp;chksm=96d8315a5e460ca139eabe1d9cbf5f8f7612c7d4d4c88a99d2e993dda011a5619748857e922c&amp;idx=1&amp;mid=2247498936&amp;sn=561c185d6f4d4852a767f53628356423#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_27岁研究员连辞两大ai实验室斥拿命下注" tabindex="-1"><a class="header-anchor" href="#_27岁研究员连辞两大ai实验室斥拿命下注"><span>27岁研究员连辞两大AI实验室斥拿命下注</span></a></h3><p>Jacob Coxon称，OpenAI未内化超级智能风险，Anthropic认清风险却停不下AI竞赛，无公司能单独造安全AI，最快明年底AI或失控，多位头部AI人物呼吁政府介入踩刹车。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f00a0f0e7fb20c037ad1e065e4c98e3c27346edfe57b069740d8bebce2be664907fc447fb1e4&amp;idx=2&amp;mid=2652724327&amp;sn=64b670b17f99353b26925e95b0a18035#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="苹果首款折叠屏iphone-duo发布" tabindex="-1"><a class="header-anchor" href="#苹果首款折叠屏iphone-duo发布"><span>苹果首款折叠屏iPhone Duo发布</span></a></h3><p>苹果发布首款折叠屏iPhone Duo，国行起售价15999元，全产品线搭载Apple Intelligence，Siri打通超30万款APP，库克正式交棒，苹果结束挤牙膏发力AI与折叠屏。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e93829ba1eb95f0d98ec91734e463331cb8e47b1b9c49c1b1f3462edba66c008ddb7f1f8d2a7&amp;idx=1&amp;mid=2247920878&amp;sn=fd72a1a4e10996085f1d2fdce5fa80c6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="七万门店实测-具身机器人落地超市盘点" tabindex="-1"><a class="header-anchor" href="#七万门店实测-具身机器人落地超市盘点"><span>七万门店实测：具身机器人落地超市盘点</span></a></h3><p>汉朔科技与X-Era Lab联合推进具身机器人落地零售门店，依托近7万家门店的电子价签底座，搭配原生世界动作模型，探索让具身智能从Demo变为可商用稳定生产系统，零售是被低估的具身智能试金石。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e98df51056ac4fd4d9c9607985c50c6c2a61c026e58d3c630fd94a506cebe96575bc3f197dfd&amp;idx=1&amp;mid=2247920660&amp;sn=8cad47067eaf27d0126c36fa230eb5e6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="清华上交提出光计算实用化技术路线图" tabindex="-1"><a class="header-anchor" href="#清华上交提出光计算实用化技术路线图"><span>清华上交提出光计算实用化技术路线图</span></a></h3><p>清华大学戴琼海团队联合上海交大课题组，提出光计算实用化首个统一评价框架，针对不同场景划定实用化门槛，指明需转向多指标协同优化推动落地。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86f2d4cd1ce1603719d65d86b4baf5411c67957255921ee4bbc89bad62d389cdd8a046890d47&amp;idx=1&amp;mid=2649804720&amp;sn=abaa6023ababaa6d105fad0c92bf1e21#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="梅涛ai视频新品vivago-r1上线" tabindex="-1"><a class="header-anchor" href="#梅涛ai视频新品vivago-r1上线"><span>梅涛AI视频新品Vivago R1上线</span></a></h3><p>智象未来推出AI视频创作智能体Vivago R1，主打告别抽卡式生成的确定性交付，采用多Agent系统编排承接复杂度，可稳定输出5分钟连贯视频，实测稳定性不错，单条生成成本约百元，个人使用略贵。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9dd7a1b46e306b9784f7fa56be94fe5a384d8f85a6ba2f63bc05898bb82b8d6702936e69492&amp;idx=2&amp;mid=2247920911&amp;sn=ece974398f4c42dceee4c4584ef3fe09#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="阿里发布新版qoder编程智能体工作台" tabindex="-1"><a class="header-anchor" href="#阿里发布新版qoder编程智能体工作台"><span>阿里发布新版Qoder编程智能体工作台</span></a></h3><p>特工小师：阿里发布新版Qoder，转型为面向全岗位的编程智能体工作台，无代码基础用户也可1小时内交付定制工具，AI Agent下半场比拼端到端交付与人机协作。<a href="https://mp.weixin.qq.com/s?__biz=MzYyMTY1NDA0Nw==&amp;chksm=fed4fc833df9b7ce1b62786d5399e241319c5a4a87500c1b3182629ff4e04ac7809598a08c2b&amp;idx=1&amp;mid=2247520943&amp;sn=34824df47414f508e77a6d408c293213#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包工作更新-实测后我给满分" tabindex="-1"><a class="header-anchor" href="#豆包工作更新-实测后我给满分"><span>豆包工作更新 实测后我给满分</span></a></h3><p>新智元实测字节跳动豆包工作最新更新，三大功能解决AI办公说不清流程、够不着本地文件、锁死设备三大痛点，让AI适配打工人工作习惯，体验极佳获满分评价。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f05d2f164fc38720f5cb7854d580ea1b6a1855feec283a00f554ef55b1aa272960b5373942be&amp;idx=1&amp;mid=2652724428&amp;sn=d9007b8bd62491fd3e87401ca86527e8#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="gpt-6破多项数学难题引学界争议" tabindex="-1"><a class="header-anchor" href="#gpt-6破多项数学难题引学界争议"><span>GPT-6破多项数学难题引学界争议</span></a></h3><p>OpenAI研究员：AI可死磕数学细节、不会被错误思路污染，生成证明比人类更简洁优雅；未来AI承担推导，人类核心价值转向框架搭建与认知整合，成果引发学界争议。<a href="https://mp.weixin.qq.com/s?__biz=Mzg4NDQwNTI0OQ==&amp;chksm=ce6fa68c72c856c076f7dc3b72c6e13c7b10fa9d8f3610ffb97b5e25123188049cff01bd80f3&amp;idx=1&amp;mid=2247590630&amp;sn=18c02b78ae277c2b3b07668527c13587#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="astra-computer-use能力原理解析" tabindex="-1"><a class="header-anchor" href="#astra-computer-use能力原理解析"><span>Astra Computer Use能力原理解析</span></a></h3><p>Kyle Jeong：现有纯视觉Computer Use模型受窗口尺寸限制易出错；Astra结合无障碍树与Codex架构，速度精度更优，其能力出圈正推动Agent渗透更多白领长尾工作场景。<a href="https://mp.weixin.qq.com/s?__biz=Mzg2OTY0MDk0NQ==&amp;chksm=cf6aa101c447e159424ae710241b533ff9a223d8040f4b86e32e8d8949d7713099875a585d1c&amp;idx=1&amp;mid=2247526927&amp;sn=e50671a618de74455b7b4919492b6038#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="沐神空降小红书-在线答疑ai问题" tabindex="-1"><a class="header-anchor" href="#沐神空降小红书-在线答疑ai问题"><span>沐神空降小红书 在线答疑AI问题</span></a></h3><p>李沐在小红书开展AMA答疑，针对AI时代学习、职业选择、技术趋势等热门问题给出解答，称Agent是能力放大器，AI将替代99%人工翻译，具身智能短期有泡沫长期有前景。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85ba0853142b746f3e908ca563f49d3cdf8ce0b8a01ee9024bd99bbe92abe78596f3fe7a9ca7&amp;idx=2&amp;mid=2651055972&amp;sn=79a359d1bffb0e42556f185751aedd38#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_2026-ai与机器人闯入艺术现场" tabindex="-1"><a class="header-anchor" href="#_2026-ai与机器人闯入艺术现场"><span>2026：AI与机器人闯入艺术现场</span></a></h3><p>MANA盘点2026年全球16组AI与机器人艺术实践，当前机器已从创作工具转变为可感知、能协作的创作参与者，艺术讨论重点转向“机器以何种身份参与创作”。<a href="https://mp.weixin.qq.com/s?__biz=MzI0MDQxNTI2OQ==&amp;chksm=e8a75ef0f0d91c0e37c811fc367acf49bc851a62ae2f6815e0767b1965a6ad018e522b7412ac&amp;idx=1&amp;mid=2247996163&amp;sn=b1340d356845eaa475fff7adf012b997#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="uber-智能体请求涨9-4倍-ai账单不涨" tabindex="-1"><a class="header-anchor" href="#uber-智能体请求涨9-4倍-ai账单不涨"><span>Uber：智能体请求涨9.4倍 AI账单不涨</span></a></h3><p>Uber：智能体请求半年增长9.4倍，通过分层模型选型、token优化缓存、MCP效率改进等手段，单位请求成本降34%，单会话成本降52%，实现规模增长同时AI总支出稳定，方法论具备普适性。<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fa0591e9d3b23b7644369fd8c4d0dce65e54cb5abe372b0c7a28c92aac9ec7532e786522db7b&amp;idx=2&amp;mid=2247666895&amp;sn=a1371750f9952b6b39ece9dc77113592#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai搜索选型-mongodb还是向量库" tabindex="-1"><a class="header-anchor" href="#ai搜索选型-mongodb还是向量库"><span>AI搜索选型：MongoDB还是向量库？</span></a></h3><p>作者：做AI搜索，关键词与向量检索各有所长，合格系统需二者结合；千万级文档内小团队用MongoDB足够，亿级核心场景才需专用组件组合。<a href="https://mp.weixin.qq.com/s?__biz=MzAxNTA3MDY1NA==&amp;chksm=8de386a3a90c7cdd1bc984854fc6a7c0c8dbd7b551238f013921ec70c50af6e1b6a241e4076d&amp;idx=1&amp;mid=2455895836&amp;sn=84b2fc41a022b1ed755ce583dda820c4#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="蚂蚁百灵开源多模态大模型ling-3-0-flash-vl" tabindex="-1"><a class="header-anchor" href="#蚂蚁百灵开源多模态大模型ling-3-0-flash-vl"><span>蚂蚁百灵开源多模态大模型Ling-3.0-flash-VL</span></a></h3><p>蚂蚁百灵开源多模态模型Ling-3.0-flash-VL，采用MoE稀疏架构，1240亿总参数推理仅激活55亿，支持图文视频及软件界面理解，部署门槛仍较高，为开发者提供新选择。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cf2f88cc3afb3e101dd25048d60c413cdc628e5e0aca6b0e01750c8b7cf7aed41ef9fff7a9b6&amp;idx=1&amp;mid=2247526877&amp;sn=36a7b7a7ad1f5176c1c59a56fd4ee328#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="耶鲁新方法推动大模型自进化" tabindex="-1"><a class="header-anchor" href="#耶鲁新方法推动大模型自进化"><span>耶鲁新方法推动大模型自进化</span></a></h3><p>耶鲁等多校研究者提出INFUSER方法，摒弃以难度筛选自进化训练题的思路，用影响力分数选对当前模型提升最有价值的题目，实现双模型协同进化，推理能力提升显著。<a href="https://mp.weixin.qq.com/s?__biz=MzI3ODgwODA2MA==&amp;chksm=ea2d93750c223f974fbefc5f879aaec0e10cf49de4c5b1d4070e7acfbbb8093b90bc7b532b4d&amp;idx=1&amp;mid=2247548481&amp;sn=cc6414387f6df01b7dbbaff2aefa3ac2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="amp开创机器人操作学习新范式" tabindex="-1"><a class="header-anchor" href="#amp开创机器人操作学习新范式"><span>AMP开创机器人操作学习新范式</span></a></h3><p>黄浩杰提出全新机器人操作学习范式AMP，将高维3D机器人动作转化为图像像素分类问题，在多个真机任务中，成功率较现有基线提升50%-70%，推理速度更快，精度达毫米级。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=859e44fedee33f0a680f1d3be54cfd982b6b61ec26798b5b39564d2380a9c2bf78ae46712940&amp;idx=2&amp;mid=2651055887&amp;sn=ee31e2172a9f7fd11b7d795fbc45b12e#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="浙大字节港中深终结3d高斯冗余" tabindex="-1"><a class="header-anchor" href="#浙大字节港中深终结3d高斯冗余"><span>浙大字节港中深终结3D高斯冗余</span></a></h3><p>浙大、字节跳动、港中深团队：针对3DGS跨视角冗余问题，提出以人为中心的PointSplat框架，从根源减少冗余，大幅压缩3D体积，适配实时沉浸式直播，推动3DGS范式迁移。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=913848e9bf22bcbfcf43567e89f7497e8a914d40bff8e1d8c977b2dc668f0dad55e4eb18c775&amp;idx=1&amp;mid=2247744747&amp;sn=b5dda1aff09e6ca456b15b8df32e0651#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="capo-slt拿下中文手语翻译三项最高分" tabindex="-1"><a class="header-anchor" href="#capo-slt拿下中文手语翻译三项最高分"><span>CAPO-SLT拿下中文手语翻译三项最高分</span></a></h3><p>vivo AI Lab团队：针对手语翻译自回归生成中无视觉支撑的错误累积问题，提出置信度感知动态更新策略CAPO-SLT，不修改原有主干网络，中文手语翻译三项指标居首，成果将登EMNLP&#39;26。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e98d5a8cdf42a21ad13fbfe4bd6c9a1553f03fa96967ab9e36e85d4dae8cf3ea4a5e99e839c4&amp;idx=3&amp;mid=2247920660&amp;sn=62b04e2178d1ec845b27297a21a1c704#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',49)]))}const s=a(i,[["render",c]]),t=JSON.parse('{"path":"/posts/2026-09-10.html","title":"AI日报：黄仁勋翻车，谷歌TPU凿穿CUDA护城河; Ox Alpha揭晓为GLM-5.3-Flash; 27岁研究员连辞两大AI实验室斥拿命下注","lang":"zh-CN","frontmatter":{"date":"2026-09-10T00:00:00.000Z","title":"AI日报：黄仁勋翻车，谷歌TPU凿穿CUDA护城河; Ox Alpha揭晓为GLM-5.3-Flash; 27岁研究员连辞两大AI实验室斥拿命下注"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"黄仁勋翻车，谷歌TPU凿穿CUDA护城河","slug":"黄仁勋翻车-谷歌tpu凿穿cuda护城河","link":"#黄仁勋翻车-谷歌tpu凿穿cuda护城河","children":[]},{"level":3,"title":"Ox Alpha揭晓为GLM-5.3-Flash","slug":"ox-alpha揭晓为glm-5-3-flash","link":"#ox-alpha揭晓为glm-5-3-flash","children":[]},{"level":3,"title":"27岁研究员连辞两大AI实验室斥拿命下注","slug":"_27岁研究员连辞两大ai实验室斥拿命下注","link":"#_27岁研究员连辞两大ai实验室斥拿命下注","children":[]},{"level":3,"title":"苹果首款折叠屏iPhone Duo发布","slug":"苹果首款折叠屏iphone-duo发布","link":"#苹果首款折叠屏iphone-duo发布","children":[]},{"level":3,"title":"七万门店实测：具身机器人落地超市盘点","slug":"七万门店实测-具身机器人落地超市盘点","link":"#七万门店实测-具身机器人落地超市盘点","children":[]},{"level":3,"title":"清华上交提出光计算实用化技术路线图","slug":"清华上交提出光计算实用化技术路线图","link":"#清华上交提出光计算实用化技术路线图","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"梅涛AI视频新品Vivago R1上线","slug":"梅涛ai视频新品vivago-r1上线","link":"#梅涛ai视频新品vivago-r1上线","children":[]},{"level":3,"title":"阿里发布新版Qoder编程智能体工作台","slug":"阿里发布新版qoder编程智能体工作台","link":"#阿里发布新版qoder编程智能体工作台","children":[]},{"level":3,"title":"豆包工作更新 实测后我给满分","slug":"豆包工作更新-实测后我给满分","link":"#豆包工作更新-实测后我给满分","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"GPT-6破多项数学难题引学界争议","slug":"gpt-6破多项数学难题引学界争议","link":"#gpt-6破多项数学难题引学界争议","children":[]},{"level":3,"title":"Astra Computer Use能力原理解析","slug":"astra-computer-use能力原理解析","link":"#astra-computer-use能力原理解析","children":[]},{"level":3,"title":"沐神空降小红书 在线答疑AI问题","slug":"沐神空降小红书-在线答疑ai问题","link":"#沐神空降小红书-在线答疑ai问题","children":[]},{"level":3,"title":"2026：AI与机器人闯入艺术现场","slug":"_2026-ai与机器人闯入艺术现场","link":"#_2026-ai与机器人闯入艺术现场","children":[]},{"level":3,"title":"Uber：智能体请求涨9.4倍 AI账单不涨","slug":"uber-智能体请求涨9-4倍-ai账单不涨","link":"#uber-智能体请求涨9-4倍-ai账单不涨","children":[]},{"level":3,"title":"AI搜索选型：MongoDB还是向量库？","slug":"ai搜索选型-mongodb还是向量库","link":"#ai搜索选型-mongodb还是向量库","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"蚂蚁百灵开源多模态大模型Ling-3.0-flash-VL","slug":"蚂蚁百灵开源多模态大模型ling-3-0-flash-vl","link":"#蚂蚁百灵开源多模态大模型ling-3-0-flash-vl","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"耶鲁新方法推动大模型自进化","slug":"耶鲁新方法推动大模型自进化","link":"#耶鲁新方法推动大模型自进化","children":[]},{"level":3,"title":"AMP开创机器人操作学习新范式","slug":"amp开创机器人操作学习新范式","link":"#amp开创机器人操作学习新范式","children":[]},{"level":3,"title":"浙大字节港中深终结3D高斯冗余","slug":"浙大字节港中深终结3d高斯冗余","link":"#浙大字节港中深终结3d高斯冗余","children":[]},{"level":3,"title":"CAPO-SLT拿下中文手语翻译三项最高分","slug":"capo-slt拿下中文手语翻译三项最高分","link":"#capo-slt拿下中文手语翻译三项最高分","children":[]}]}],"git":{"updatedTime":1789894946000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"121ec5f32fdc195f0f00aa74cb6e5c6b0a22ce54","time":1789894946000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-20T09:02:26.351Z"}]},"filePathRelative":"posts/2026-09-10.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-10 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>黄仁勋翻车，谷歌TPU凿穿CUDA护城河</h3>\\n<p>SemiAnalysis：第三方测试显示，谷歌第七代TPU Ironwood推理每美元性能最高领先英伟达B200达50%，领先B300近一倍，谷歌代码重构打破了CUDA生态壁垒。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0e45c67680643dfec87ade4e15bf24774674f47ce9a9ff1b25c3173ffb4c06f280dd96071b8&amp;idx=2&amp;mid=2652724610&amp;sn=fcfa4e1850bd0fe059c6857ffe6823eb#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,t as data};
